import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Upload, Link as LinkIcon, FileText, Loader2 } from 'lucide-react';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

export default function Home() {
  const navigate = useNavigate();
  const [driveUrl, setDriveUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showJDModal, setShowJDModal] = useState(false);
  const [jobDescription, setJobDescription] = useState('');

  const handleDriveSubmit = async (e) => {
    e.preventDefault();
    if (!driveUrl) return;
    setLoading(true); setError(null);
    try {
      const res = await axios.post(`${API_URL}/verify-drive-link`, { url: driveUrl });
      navigate(`/session/${res.data.sessionId}`);
    } catch (err) {
      setError(err.response?.data?.error || err.message);
      setLoading(false);
    }
  };

  const handleFileUpload = async (event, type) => {
    const files = event.target.files;
    if (!files.length) return;
    setLoading(true); setError(null);

    const formData = new FormData();
    if (type === 'resume') {
      formData.append('resume', files[0]);
      if (jobDescription.trim()) {
        formData.append('jobDescription', jobDescription);
      }
    } else {
      Array.from(files).forEach(f => formData.append('certificates', f));
    }

    try {
      const endpoint = type === 'resume' ? '/verify-resume' : '/verify-certificates';
      const res = await axios.post(`${API_URL}${endpoint}`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      navigate(`/session/${res.data.sessionId}`);
    } catch (err) {
      setError(err.response?.data?.error || err.message);
      setLoading(false);
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="home-container"
    >
      <div style={{ textAlign: 'center', marginBottom: '48px' }}>
        <h1 style={{ fontSize: '3rem', marginBottom: '16px', background: 'linear-gradient(to right, #f8fafc, #94a3b8)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
          Intelligence Platform
        </h1>
        <p style={{ color: 'var(--text-secondary)', fontSize: '1.25rem', maxWidth: '600px', margin: '0 auto' }}>
          Verify credentials instantly using AI. Upload a resume, paste a Google Drive link, or drop your certificates directly.
        </p>
      </div>

      {error && (
        <div style={{ background: 'var(--status-fake-bg)', color: 'var(--status-fake)', padding: '16px', borderRadius: '8px', marginBottom: '24px', border: '1px solid var(--status-fake)', textAlign: 'center' }}>
          {error}
        </div>
      )}

      {loading && (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', margin: '40px 0', color: 'var(--accent-primary)' }}>
          <Loader2 size={48} className="animate-spin" />
          <p style={{ marginTop: '16px', fontWeight: '500' }}>Processing your request... This might take a moment.</p>
        </div>
      )}

      {!loading && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '24px' }}>

          {/* Resume Upload */}
          <motion.div whileHover={{ y: -5 }} className="glass-panel" onClick={() => setShowJDModal(true)} style={{ position: 'relative', cursor: 'pointer', textAlign: 'center' }}>

            <div style={{ background: 'rgba(59, 130, 246, 0.1)', width: '64px', height: '64px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px', color: 'var(--accent-primary)' }}>
              <FileText size={32} />
            </div>
            <h3 style={{ fontSize: '1.25rem', marginBottom: '8px' }}>Analyze Resume</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>Upload PDF or DOCX. We'll extract and verify all linked certificates automatically.</p>
          </motion.div>

          {/* Drive Link */}
          <motion.div whileHover={{ y: -5 }} className="glass-panel">
            <div style={{ textAlign: 'center' }}>
              <div style={{ background: 'rgba(139, 92, 246, 0.1)', width: '64px', height: '64px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px', color: 'var(--accent-secondary)' }}>
                <LinkIcon size={32} />
              </div>
              <h3 style={{ fontSize: '1.25rem', marginBottom: '8px' }}>Drive Link Verification</h3>
              <p style={{ color: 'var(--text-secondary)', fontSize: '0.875rem', marginBottom: '16px' }}>Paste a public Google Drive or direct file link.</p>
            </div>
            <form onSubmit={handleDriveSubmit} style={{ display: 'flex', gap: '8px' }}>
              <input 
                type="url" 
                placeholder="https://drive.google.com/..." 
                value={driveUrl}
                onChange={(e) => setDriveUrl(e.target.value)}
                required
              />
              <button type="submit" className="btn-primary">Verify</button>
            </form>
          </motion.div>

          {/* Batch Upload */}
          <motion.div whileHover={{ y: -5 }} className="glass-panel" style={{ position: 'relative', cursor: 'pointer', textAlign: 'center' }}>
            <input 
              type="file" 
              accept=".pdf,image/*" 
              multiple
              onChange={(e) => handleFileUpload(e, 'certificates')}
              style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer' }}
              title="Upload Certificates"
            />
            <div style={{ background: 'rgba(16, 185, 129, 0.1)', width: '64px', height: '64px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px', color: 'var(--status-real)' }}>
              <Upload size={32} />
            </div>
            <h3 style={{ fontSize: '1.25rem', marginBottom: '8px' }}>Batch Certificates</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>Upload up to 10 certificates (PDF, JPG, PNG) at once for verification.</p>
          </motion.div>

        </div>
      )}

      {/* JD Modal */}
      {showJDModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50 }}>
          <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="glass-panel" style={{ width: '100%', maxWidth: '500px', background: 'var(--bg-surface)' }}>
            <h3 style={{ fontSize: '1.5rem', marginBottom: '16px' }}>ATS Analysis Setup</h3>
            <p style={{ color: 'var(--text-secondary)', marginBottom: '16px', fontSize: '0.875rem' }}>
              Paste the Job Description below to generate an AI-powered ATS Match Score. (Optional)
            </p>
            <textarea 
              style={{ width: '100%', height: '150px', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--glass-border)', color: 'var(--text-primary)', padding: '12px', borderRadius: '8px', marginBottom: '16px', resize: 'vertical' }}
              placeholder="We are looking for a Senior Software Engineer with..."
              value={jobDescription}
              onChange={(e) => setJobDescription(e.target.value)}
            />
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
              <button className="btn-secondary" onClick={() => setShowJDModal(false)}>Cancel</button>
              <div style={{ position: 'relative' }}>
                <input 
                  type="file" 
                  accept=".pdf,.doc,.docx" 
                  onChange={(e) => { setShowJDModal(false); handleFileUpload(e, 'resume'); }}
                  style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer' }}
                  title="Upload Resume"
                />
                <button className="btn-primary">Upload Resume</button>
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </motion.div>
  );
}
